<div class="container-fluid px-3 px-lg-4 py-4"><p class="eyebrow mb-2">PURCHASING / GOODS RECEIPT</p><h1 class="h3 mb-4">{{ $editing ? 'แก้ไข' : 'สร้าง' }} Goods Receipt</h1><div class="alert alert-warning border-0 small">เอกสารนี้ยังไม่ลง Stock, Cost Layer หรือ GL; หลังบันทึกสามารถอนุมัติ/ยกเลิกตามสิทธิ์ได้</div><form id="goods-receipt-form" method="POST" action="{{ $editing ? route($moduleRoutePrefix.'.purchase-receipts.update',$receipt) : route($moduleRoutePrefix.'.purchase-receipts.store') }}">@csrf @if($editing) @method('PUT') @endif<div class="card border-0 shadow-sm mb-4"><div class="card-body row g-3">@if(!$editing)<div class="col-md-6"><label class="form-label">Purchase Order</label><select id="receipt-po" class="form-select" name="purchase_order_id" data-url="{{ route($moduleRoutePrefix.'.purchase-receipts.purchase-options') }}" required></select></div>@else<div class="col-md-6"><label class="form-label">Purchase Order</label><input class="form-control" value="{{ $receipt->purchaseOrder?->document_number ?? $receipt->purchase_order_id }}" disabled></div>@endif@if($editing)<div class="col-md-3"><label class="form-label">เลขที่ Receipt</label><input class="form-control" value="{{ $receipt->receipt_number }}" disabled></div>@endif<div class="col-md-3"><label class="form-label">วันที่รับ</label><input class="form-control" type="date" name="business_date" value="{{ $today }}" required><div class="form-text">ระบบออกเลขตามสาขาและวันที่รับ</div></div><div class="col-12"><label class="form-label">หมายเหตุ</label><textarea class="form-control" name="description" rows="2">{{ $editing ? $receipt->description : '' }}</textarea></div>@if(!$editing)<input type="hidden" name="idempotency_key" value="gr-{{ now()->format('YmdHisv') }}">@endif</div></div><div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">รายการรับสินค้า</h2><button class="btn btn-app-soft btn-sm" type="button" id="add-receipt-line">เพิ่มรายการ</button></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>รายการ PO</th><th>จำนวนรับ</th><th>ต้นทุนรวม</th><th></th></tr></thead><tbody id="receipt-lines"></tbody></table></div><div class="mt-4"><button class="btn btn-dark" type="submit">บันทึกร่าง</button> <a class="btn btn-outline-secondary" href="{{ route($moduleRoutePrefix.'.purchase-receipts.index') }}">ยกเลิก</a></div></div></div></form></div>
