@push('scripts')
<script>$(function(){var po=$('#receipt-po'),body=$('#receipt-lines'),lineUrl='{{ route($moduleRoutePrefix.'.purchase-receipts.line-options') }}',n=0,available=[];function initSelect(s){window.erpInitSelect2(s,{theme:'bootstrap-5',placeholder:'ค้นหา PO line',allowClear:true});}function addLine(option){var i=n++,row=$('<tr><td><select class="form-select js-line" name="lines['+i+'][purchase_order_line_id]" required></select><div class="small text-secondary js-remaining"></div></td><td><input class="form-control text-end js-qty" type="number" min="0.00000001" step="0.00000001" name="lines['+i+'][purchase_qty]" required></td><td><input class="form-control text-end" type="number" min="0" step="0.00000001" name="lines['+i+'][total_cost]" value="0"></td><td><button type="button" class="btn btn-sm btn-outline-danger js-remove">ลบ</button></td></tr>');body.append(row);initSelect(row.find('.js-line'));if(option){row.find('.js-line').append(new Option(option.text,option.id,true,true)).trigger('change');applyOption(row,option);}else{available.forEach(function(o){row.find('.js-line').append(new Option(o.text,o.id,false,false));});}}function applyOption(row,option){row.find('.js-qty').attr('max',option.remaining_quantity).val(option.purchase_quantity||option.remaining_quantity);row.find('.js-remaining').text('คงเหลือ '+option.remaining_quantity);row.find('input[name$="[total_cost]"]').val(option.total_cost||0);}function loadLines(id){body.empty();$.getJSON(lineUrl,{purchase_order_id:id}).done(function(data){available=data.results||[];available.forEach(addLine);if(!available.length)Swal.fire({icon:'info',text:'PO นี้รับครบแล้วหรือไม่มีรายการสินค้า'});});}if(po.length){window.erpInitSelect2(po,{theme:'bootstrap-5',placeholder:'ค้นหา Purchase Order',allowClear:true,ajax:{url:po.data('url'),delay:250,data:function(p){return{q:p.term||'',page:p.page||1}},processResults:function(x){return x}}});po.on('change',function(){if(po.val())loadLines(po.val());else body.empty();});}else{@foreach($receipt?->lines ?? [] as $line) addLine({id:{{ $line->purchase_order_line_id }},text:'PO line #{{ $line->purchase_order_line_id }}',purchase_quantity:'{{ $line->purchase_quantity }}',remaining_quantity:'{{ $line->purchase_quantity }}',total_cost:'{{ $line->total_cost }}'}); @endforeach}$('#add-receipt-line').on('click',function(){if(po.length&&po.val())addLine();});body.on('change','.js-line',function(){var row=$(this).closest('tr'),o=available.find(function(x){return String(x.id)===String($(this).val());}.bind(this));if(o)applyOption(row,o);});body.on('click','.js-remove',function(){$(this).closest('tr').remove();});window.erpAjaxForm({form:'#goods-receipt-form',redirect:true});});</script>
@endpush
